type Event struct {
	Kind string
	Msg  string
}

type Notifier interface {
	Notify(ctx context.Context, ev Event) error
}

type SlackNotifier struct{ hook string }

func (s *SlackNotifier) Notify(ctx context.Context, ev Event) error {
	return post(ctx, s.hook, ev)
}

func NewNotifier(cfg Config) Notifier {
	var s *SlackNotifier
	if cfg.SlackHook != "" {
		s = &SlackNotifier{hook: cfg.SlackHook}
	}
	return s
}

func Dispatch(ctx context.Context, n Notifier, ev Event) {
	if n == nil {
		return
	}
	if err := n.Notify(ctx, ev); err != nil {
		slog.Error("notify failed", "err", err)
	}
}
